import urllib.request, json
u="https://data.cityofnewyork.us/resource/wq7q-htne.json?$limit=500"
d=json.load(urllib.request.urlopen(u))
years=list(range(2005,2025))
tot={y:0.0 for y in years}
pc={y:0.0 for y in years}
for r in d:
    if r.get('inventory_type')!='GPC': continue
    if r.get('source_units')!='VMT': continue
    for y in years:
        k=f'cy_{y}_consumed'
        if k in r:
            tot[y]+=float(r[k])
            if 'Passenger cars' in r.get('category_full',''):
                pc[y]+=float(r[k])
for y in years:
    print(y, round(tot[y]/1e9,3), round(pc[y]/1e9,3))
EOF

